import './App.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCode } from '@fortawesome/free-solid-svg-icons';

function App() {
  const slides = document.querySelectorAll('.slide');
  let currentSlide = 0;
  const slideInterval = setInterval(() => {
    slides[currentSlide].classList.remove('active');
    currentSlide = (currentSlide + 1) % slides.length;
    slides[currentSlide].classList.add('active');
  }, 3000);

  return (
    <div className="Container">
      <header className='header'>
        <h2 className='myName'><FontAwesomeIcon icon={faCode} /> Elijah Kalosa <FontAwesomeIcon icon={faCode} /></h2>
        <div className='menuBar'>
          <ul className='menuList'>
            <li className='menuItem'>Home</li>
            <li className='menuItem'>About</li>
            <li className='menuItem'>Projects</li>
            <li className='menuItem'>Contact</li>
          </ul>
        </div>
      </header>
      <main className='mainContent'>
        <section className='introduction'>
          <h1 className='cTA'>
            Meet Elijah Kalosa a <div className='slideShow'>
              <div className='slide'>Web Developer</div>
              <div className='slide'>Software Engineer</div>
              <div className='slide'>Tech Enthusiast</div>
            </div>
            {
              /* The slides will automatically change every 3 seconds */
              /* The 'active' class should be added to the first slide in CSS */
              /* Ensure to add CSS for the 'active' class to show the current slide */
              /* You can also add transition effects for a smoother experience */
              slides[currentSlide].classList.add('active')
              /* This is a simple implementation; consider using React state for better control */
              /* Note: The above code is for demonstration; in a real React app, you would use state and effects */
              /* to manage the slideshow instead of directly manipulating the DOM */
              /* This is a basic example; for production, consider using React state and effects */

            }

          </h1>
        </section>
      </main>
    </div>
  )
}

export default App;
